import{_ as t,o as p,c as e,a4 as r}from"./chunks/framework.DzJZdBQK.js";const k=JSON.parse('{"title":"写作课作业-115","description":"","frontmatter":{"date":"2021-03-21T21:19:08","title":"写作课作业-115","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[],"relativePath":"posts/homework/115.md","filePath":"posts/homework/115.md"}'),l={name:"posts/homework/115.md"};function s(i,o,n,a,c,g){return p(),e("div",null,[...o[0]||(o[0]=[r('<blockquote><p>《区块链小白书》之《比特币 10.小白如何购买比特币》</p></blockquote><p>这一章节是一篇教程，只是对没有更新的内容做些增补。</p><hr><p>2020 年 6 月，我投资了 “水龙头APP”。 —— <strong>因为我自己天天用，所以，只能投资了</strong>…… 正如我十年前买苹果股票一样，天天用的东西，竟然能投资的话，那么最好投资它。</p><p>“水龙头” 的工作原理很简单：</p><blockquote><p>通过它在各大电商平台上（淘宝、天猫、京东、拼多多）购物的时候，它会在月底帮你把返利攒起来换成 <strong>比特币</strong> 交给你……</p></blockquote><p>这个简单的工作原理决定了很多重要的特性：</p><blockquote><ul><li>绝对零风险</li><li>甚至零投入</li><li>符合 “蛋壳投资原则”……</li></ul></blockquote><p>第一条，对李笑来来说是至关重要的，因为我的身份敏感，所以，但凡有一点点风险，我也不会直接推荐。对用户来说，必须是真正的<strong>零风险</strong>，才是李笑来可以认真推荐的产品。</p><p>第二条，是真正意义上的 <strong>“普惠”</strong>，99% 以上的人不参与投资的本质理由都一样：“没啥钱可用来投资” —— 可现在，竟然可以零成本参与投资，这难道不是很神奇吗？</p><p>而最后的第三条，<strong>“蛋壳投资原则”</strong>，也非常非常重要，其原因请参阅我认真创作的<a href="https://ri.firesbox.com/#/cn/" target="_blank" rel="noreferrer">《定投改变命运》（第三版）</a>中的内容：</p><blockquote><p><a href="https://ri.firesbox.com/#/cn/" target="_blank" rel="noreferrer">https://ri.firesbox.com/#/cn/</a></p></blockquote><p>万一（我是说，万一，而不是一定）将来比特币再涨个几倍几十倍，那今天看起来 “少得可怜” 的 3～5% 的返利，可能会让你今天的消费成本削减为零……</p><p>我自己用了一段时间，觉得还是挺可怕的 —— 每个月网购金额差不多三五万的李笑来，能 <strong>“凭空” 多出</strong> 价值一千多元人民币的比特币……</p><p>所以，现在我买任何东西的时候，都会多花几秒钟，从水龙头的 “超级搜索” 开始…… 这几秒钟绝对值当啊！</p><p>比如，今天我的一位微信好友（胡子晗）教我弹吉他的时候，提起有一种可以让指甲更硬一点的指甲油，日本产品，牌子是 Kaina…… 我还真是第一次知道还有这种东西！我的指甲太薄，这些年从来没有留起来过，所以尽量只用拨片…… 现在，我倒是想象听听留起指甲后的音色了！</p><p>于是，我打开水龙头 APP，在淘宝找到这个商品，下单购买，然后，账户里多了价值几块钱人民币的比特币……</p><p><img src="https://blockchainlittlebook.com/images/shuilongtou.png" alt="img"></p><p>使用步骤很简单：</p><blockquote><ol><li>识别第一张海报中的二维码，下载 <strong>水龙头 APP</strong>，我的邀请码是：<code>XHCXRE</code></li><li>打开水龙头APP</li><li>搜索商品 —— 这个 “超级搜索” 能在淘宝、天猫、京东、拼多多上搜索商品…… 比如，我就要搜索 <strong>Kaina</strong> —— 这个朋友刚刚介绍给我的品牌；</li><li>水龙头帮我在淘宝上找到了这个商品…… 有的时候，有多个平台可选，自己衡量一下吧，售价、收货时间等等。然后，在此之前，你的手机里必须已经安装了这些购物平台的 APP 才可以跳转到它们上面购买……</li><li>购买的同时获得免费比特币</li><li>跳转到购物平台购买……</li></ol></blockquote><p>如此这般，你在保持正常日常消费的同时，也免费投资了比特币 —— 最好长期持有，以观后效！</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',28)])])}const m=t(l,[["render",s]]);export{k as __pageData,m as default};
